package com.mingdai.toTool.barcode.hanxin

import java.util.Base64

/**
 * 汉信码（GB/T 21049 / ISO/IEC 20830）的容量、分块和结构参数。
 *
 * 数据取自 Zint 的 hanxin.c（BSD-3-Clause）以及 CodeGlyphX 的移植版本，
 * 这里只保存压缩后的 Base64 表，运行时解码。
 */
internal object HanXinTables {
    private val totalValues = decodeUInt16("GQAlADIANgBFAFQAZAB1AIgAmwChALUAywDhAPkAEQErAUUBYQF9AZsBpgHFAeUBBgIoAksCbwKUAroC4QLyAhoDRANuA5oDxgPzAyIEUQRmBJcEyAT7BC8FZAWaBdEF6QUhBlwGlgbRBg0HSweJB8gH5QcmCGcIqgjuCDMJeQnACeAJKApxCr0KCAtUC6EL8As/DGMMtAwGDVgNrA0BDlcOrg7WDi4P")
    private val dataValues = decodeUInt16("")
    private val kValues = Base64.getDecoder().decode("AAAADhAQERITFA4PEBARERITFBQVEBEREhITExQUFREREhITExMUFBEREhISExMTERESEhISExMTERESEhISExMRERESEhISExMRERESEhISEhER")
    private val rValues = Base64.getDecoder().decode("AAAADw8REhMUFQ8PDxERExMTExUVERASERMSFBMVFBETERMRExUTFRIUERMVEhQWERMPERMVERMVEhQPERMVEBIRExUPERMVDxESFBYPERMVFxET")
    private val mValues = Base64.getDecoder().decode("AAAAAQEBAQEBAQICAgICAgICAgICAwMDAwMDAwMDAwQEBAQEBAQEBAUFBQUFBQUFBgYGBgYGBgYGBwcHBwcHBwcICAgICAgICAgJCQkJCQkJCQoK")
    private val d1Values = Base64.getDecoder().decode("")

    fun totalCodewords(version: Int): Int = totalValues[version - 1]
    fun dataCodewords(version: Int, eccLevel: Int): Int = dataValues[(eccLevel - 1) * 84 + version - 1]
    fun moduleK(version: Int): Int = kValues[version - 1].toInt() and 0xFF
    fun moduleR(version: Int): Int = rValues[version - 1].toInt() and 0xFF
    fun moduleM(version: Int): Int = mValues[version - 1].toInt() and 0xFF

    fun blockBatch(version: Int, eccLevel: Int, batch: Int): Triple<Int, Int, Int> {
        val offset = (version - 1) * 36 + (eccLevel - 1) * 9 + batch * 3
        return Triple(
            d1Values[offset].toInt() and 0xFF,
            d1Values[offset + 1].toInt() and 0xFF,
            d1Values[offset + 2].toInt() and 0xFF,
        )
    }

    private fun decodeUInt16(value: String): IntArray {
        val bytes = Base64.getDecoder().decode(value)
        return IntArray(bytes.size / 2) {
            (bytes[it * 2].toInt() and 0xFF) or ((bytes[it * 2 + 1].toInt() and 0xFF) shl 8)
        }
    }
}
